// Generated by Tekla.Technology.Akit.ScriptBuilder

using System;
using System.IO;
using System.Threading;

namespace Tekla.Technology.Akit.UserScript
{
    public class Script
    {
        private static int _started;
        private static bool _prevConnected;
        private static string _prevPath;
        private static readonly System.Collections.Generic.List<Tekla.Structures.Model.Events> _heldBridgeEvents
            = new System.Collections.Generic.List<Tekla.Structures.Model.Events>();

        public static void Run(Tekla.Technology.Akit.IScript akit)
        {
            if (Interlocked.Exchange(ref _started, 1) != 0)
                return;

            string dir = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "SaveAlertTS", "bridge");

            try
            {
                Directory.CreateDirectory(dir);
            }
            catch (Exception) { }

            int pid = System.Diagnostics.Process.GetCurrentProcess().Id;
            Log(dir, "SaveBridge iniciado pid=" + pid
                + " thread=" + Thread.CurrentThread.ManagedThreadId
                + " pool=" + Thread.CurrentThread.IsThreadPoolThread);

            RegisterModelLoadEvents(dir, pid);

            long ticks = 0;
            while (true)
            {
                try
                {
                    ProcessRequests(dir, pid);
                }
                catch (Exception ex)
                {
                    Log(dir, "Error en loop: " + ex.GetType().Name + " - " + ex.Message);
                }

                ticks++;
                if (ticks % 2 == 0)
                    CheckModelLoad(dir, pid);

                if (ticks % 25 == 0)
                    Log(dir, "Heartbeat ticks=" + ticks);

                Thread.Sleep(400);
            }
        }

        private static void RegisterModelLoadEvents(string dir, int pid)
        {
            try
            {
                var events = new Tekla.Structures.Model.Events();
                events.ModelLoad += () => OnModelLoad(dir, pid);
                events.Register();
                _heldBridgeEvents.Add(events);
                Log(dir, "Events ModelLoad registrados en el puente.");
            }
            catch (Exception ex)
            {
                Log(dir, "Events ModelLoad del puente fallaron (usando polling): "
                    + ex.GetType().Name + " - " + ex.Message);
            }
        }

        private static void OnModelLoad(string dir, int pid)
        {
            Log(dir, ">>> Evento ModelLoad disparado <<<");
            try
            {
                var model = new Tekla.Structures.Model.Model();
                if (model.GetConnectionStatus())
                {
                    string path = model.GetInfo().ModelPath;
                    _prevConnected = true;
                    _prevPath = path;
                    WriteModelMarker(dir, pid, path);
                }
            }
            catch (Exception ex)
            {
                Log(dir, "Evento ModelLoad error: " + ex.GetType().Name + " - " + ex.Message);
            }
        }

        private static void ProcessRequests(string dir, int pid)
        {
            string[] files;
            try
            {
                files = Directory.GetFiles(dir, "request_*.txt");
            }
            catch
            {
                return;
            }

            foreach (string file in files)
            {
                try
                {
                    string[] lines = File.ReadAllLines(file);

                    string requestId = GetValue(lines, "REQUESTID");
                    string pidText = GetValue(lines, "PID");

                    if (string.IsNullOrEmpty(requestId) || string.IsNullOrEmpty(pidText))
                        continue;

                    int requestPid;
                    if (!int.TryParse(pidText, out requestPid) || requestPid != pid)
                        continue;

                    TryDelete(file);

                    bool ok = false;
                    string message = "unknown error";
                    try
                    {
                        var handler = new Tekla.Structures.Model.ModelHandler();
                        ok = handler.Save("SaveAlertTS", Environment.UserName);
                        message = ok ? "saved" : "ModelHandler.Save() returned false";
                    }
                    catch (Exception ex)
                    {
                        message = ex.GetType().Name + ": " + ex.Message;
                        if (ex.InnerException != null)
                            message += " | Inner: " + ex.InnerException.Message;
                    }

                    Log(dir, "Pedido " + requestId + " -> ok=" + ok + " [" + message + "]");
                    WriteResponse(dir, requestId, ok, message);
                }
                catch (Exception ex)
                {
                    Log(dir, "Error procesando " + file + ": " + ex.Message);
                }
            }
        }

        private static void CheckModelLoad(string dir, int pid)
        {
            bool connected = false;
            string path = null;

            try
            {
                var model = new Tekla.Structures.Model.Model();
                connected = model.GetConnectionStatus();
                if (connected)
                {
                    var info = model.GetInfo();
                    path = info.ModelPath;
                    if (string.IsNullOrEmpty(path))
                        connected = false;
                }
            }
            catch (Exception ex)
            {
                Log(dir, "CheckModelLoad API error: " + ex.GetType().Name + " - " + ex.Message);
                connected = false;
                path = null;
            }

            if (!connected)
            {
                _prevConnected = false;
                _prevPath = null;
                return;
            }

            bool isNew = !_prevConnected
                || !string.Equals(_prevPath, path, StringComparison.OrdinalIgnoreCase);

            _prevConnected = true;
            _prevPath = path;

            if (!isNew)
                return;

            WriteModelMarker(dir, pid, path);
        }

        private static void WriteModelMarker(string dir, int pid, string path)
        {
            try
            {
                string marker = Path.Combine(dir, "model_" + pid + ".txt");
                string text =
                    "PID=" + pid + Environment.NewLine +
                    "MODEL=" + Sanitize(path) + Environment.NewLine +
                    "LOADEDAT=" + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + Environment.NewLine;
                File.WriteAllText(marker, text);
                Log(dir, "Modelo detectado (nuevo): " + path);
            }
            catch (Exception ex)
            {
                Log(dir, "Error escribiendo marcador de modelo: " + ex.Message);
            }
        }

        private static void WriteResponse(string dir, string requestId, bool ok, string message)
        {
            try
            {
                string path = Path.Combine(dir, "response_" + requestId + ".txt");
                string text =
                    "REQUESTID=" + requestId + Environment.NewLine +
                    "OK=" + (ok ? "true" : "false") + Environment.NewLine +
                    "MESSAGE=" + Sanitize(message) + Environment.NewLine +
                    "FINISHEDAT=" + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + Environment.NewLine;

                File.WriteAllText(path, text);
            }
            catch (Exception ex)
            {
                Log(dir, "Error escribiendo respuesta: " + ex.Message);
            }
        }

        private static string GetValue(string[] lines, string key)
        {
            string prefix = key + "=";
            foreach (string line in lines)
            {
                if (line.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                    return line.Substring(prefix.Length).Trim();
            }
            return null;
        }

        private static string Sanitize(string value)
        {
            if (string.IsNullOrEmpty(value))
                return "";
            return value.Replace("\r", " ").Replace("\n", " ");
        }

        private static void TryDelete(string file)
        {
            try
            {
                if (File.Exists(file))
                    File.Delete(file);
            }
            catch
            {
            }
        }

        private static void Log(string dir, string message)
        {
            try
            {
                string path = Path.Combine(dir, "bridge_" + System.Diagnostics.Process.GetCurrentProcess().Id + ".log");
                File.AppendAllText(path,
                    DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff") + " - " + message + Environment.NewLine);
            }
            catch
            {
            }
        }
    }
}
